using System.Text.Json;
using System.Text.RegularExpressions;

namespace PedroOS.Web.Services;

public interface IIconRegistry
{
    string GetPath(string key, int size = 32);
    string GetGlyphPath(string name);
    bool Exists(string key);
    IReadOnlyDictionary<string, IconEntry> All { get; }
}

public sealed record IconEntry(string Category, string Description, IReadOnlyList<int> Sizes);

/// <summary>
/// Central registry for pixel-art icons so views and scripts never hardcode asset paths.
/// Reads Data/icons.json generated by scripts/generate-icons.mjs.
/// </summary>
public sealed partial class IconRegistry : IIconRegistry
{
    private static readonly int[] SupportedSizes = [16, 32, 48];
    private readonly Dictionary<string, IconEntry> _icons = new(StringComparer.OrdinalIgnoreCase);
    private readonly HashSet<string> _glyphs = new(StringComparer.OrdinalIgnoreCase);
    private readonly string _basePath = "/assets/icons";

    [GeneratedRegex("^[a-z0-9-]+$", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant)]
    private static partial Regex SafeKeyRegex();

    public IconRegistry(IWebHostEnvironment env) : this(Path.Combine(env.ContentRootPath, "Data", "icons.json"))
    {
    }

    public IconRegistry(string manifestPath)
    {
        if (!File.Exists(manifestPath))
        {
            return;
        }

        using var stream = File.OpenRead(manifestPath);
        using var doc = JsonDocument.Parse(stream);
        var root = doc.RootElement;

        if (root.TryGetProperty("basePath", out var bp) && bp.GetString() is { Length: > 0 } basePath)
        {
            _basePath = basePath.TrimEnd('/');
        }

        if (root.TryGetProperty("icons", out var iconsEl) && iconsEl.ValueKind == JsonValueKind.Object)
        {
            foreach (var prop in iconsEl.EnumerateObject())
            {
                var cat = prop.Value.TryGetProperty("category", out var c) ? c.GetString() ?? "system" : "system";
                var desc = prop.Value.TryGetProperty("description", out var d) ? d.GetString() ?? prop.Name : prop.Name;
                var sizes = prop.Value.TryGetProperty("sizes", out var s) && s.ValueKind == JsonValueKind.Array
                    ? s.EnumerateArray().Select(x => x.GetInt32()).ToArray()
                    : SupportedSizes;
                _icons[prop.Name] = new IconEntry(cat, desc, sizes);
            }
        }

        if (root.TryGetProperty("glyphs", out var glyphsEl) && glyphsEl.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in glyphsEl.EnumerateArray())
            {
                if (item.GetString() is { Length: > 0 } g)
                {
                    _glyphs.Add(g);
                }
            }
        }
    }

    public IReadOnlyDictionary<string, IconEntry> All => _icons;

    public bool Exists(string key) =>
        !string.IsNullOrWhiteSpace(key) && SafeKeyRegex().IsMatch(key) && _icons.ContainsKey(key);

    public string GetPath(string key, int size = 32)
    {
        var normalizedSize = NormalizeSize(size);
        if (!string.IsNullOrWhiteSpace(key) && SafeKeyRegex().IsMatch(key) && _icons.TryGetValue(key, out var entry))
        {
            return $"{_basePath}/{entry.Category}/{key.ToLowerInvariant()}-{normalizedSize}.png";
        }

        return $"{_basePath}/system/exe-{normalizedSize}.png";
    }

    public string GetGlyphPath(string name)
    {
        if (!string.IsNullOrWhiteSpace(name) && SafeKeyRegex().IsMatch(name) && _glyphs.Contains(name))
        {
            return $"{_basePath}/ui/px-{name.ToLowerInvariant()}.svg";
        }

        return $"{_basePath}/ui/px-file.svg";
    }

    private static int NormalizeSize(int requested) =>
        requested switch
        {
            <= 16 => 16,
            <= 32 => 32,
            _ => 48,
        };
}
